 function buildScores(ratings,records,sorWeight,benchmark=2){
  const sorByTeam=new Map(records.map(d=>[d[0],d[benchmark]]));
  const standardize=values=>{
   const mean=values.reduce((sum,v)=>sum+v,0)/values.length;
   const sd=Math.sqrt(values.reduce((sum,v)=>sum+(v-mean)**2,0)/values.length);
   return values.map(v=>sd?(v-mean)/sd:0);
  };
  const feiZ=standardize(ratings.map(d=>d[1]));
  const sorZ=standardize(ratings.map(d=>sorByTeam.get(d[0])));
  const rows=ratings.map((d,i)=>({team:d[0],fei:d[1],feiRank:d[2],sor:sorByTeam.get(d[0]),feiZ:feiZ[i],sorZ:sorZ[i],score:(1-sorWeight)*feiZ[i]+sorWeight*sorZ[i]}));
  rows.sort((a,b)=>b.score-a.score||a.team.localeCompare(b.team));
  let previousKey,rank=0;
  rows.forEach((r,i)=>{const key=Math.round(r.score*1e12);if(key!==previousKey)rank=i+1;r.rank=rank;previousKey=key;});
  return rows;
 }
 function applyHeadToHead(rows,results){
  const wins=typeof results.has==='function'?results:new Set(results.map(([winner,loser])=>winner+'\u0000'+loser));
  const adjusted=rows.map(r=>({...r,unadjustedRank:r.rank}));
  for(let i=0;i<adjusted.length-1;i++){
   if(wins.has(adjusted[i+1].team+'\u0000'+adjusted[i].team)){
    [adjusted[i],adjusted[i+1]]=[adjusted[i+1],adjusted[i]];
   }
  }
  adjusted.forEach((r,i)=>{r.rank=i+1;});
  return adjusted;
 }
 function rankMSE(rows,committeeTeams,weight,headToHead=null){
  if(!committeeTeams.length)return null;
  if(headToHead){
   const scored=rows.map(r=>({...r,score:(1-weight)*r.feiZ+weight*r.sorZ})).sort((a,b)=>b.score-a.score||a.team.localeCompare(b.team));
   const ranks=new Map(applyHeadToHead(scored,headToHead).map(r=>[r.team,r.rank]));
   return committeeTeams.reduce((sum,team,i)=>sum+(ranks.get(team)-(i+1))**2,0)/(2*committeeTeams.length);
  }
  const keys=rows.map(r=>Math.round(((1-weight)*r.feiZ+weight*r.sorZ)*1e12));
  const indices=new Map(rows.map((r,i)=>[r.team,i]));
  let squared=0;
  committeeTeams.forEach((team,i)=>{
   const index=indices.get(team);
   if(index===undefined)throw new Error(`Missing committee team: ${team}`);
   const rank=1+keys.reduce((n,key)=>n+(key>keys[index]?1:0),0);
   squared+=(rank-(i+1))**2;
  });
  return squared/(2*committeeTeams.length);
 }
 function fitWeight(ratings,records,committeeTeams,benchmark,headToHead=null){
  if(!committeeTeams.length)return null;
  const rows=buildScores(ratings,records,0,benchmark);
  // Ranks change only when two affine scores cross. Check every interval and
  // every crossing (where tied competition ranks can have a distinct loss).
  const crossings=[0,1];
  for(let i=0;i<rows.length;i++)for(let j=i+1;j<rows.length;j++){
   const a=rows[i],b=rows[j];
   const denominator=(a.sorZ-a.feiZ)-(b.sorZ-b.feiZ);
   if(Math.abs(denominator)<1e-15)continue;
   const weight=(b.feiZ-a.feiZ)/denominator;
   if(weight>0&&weight<1)crossings.push(weight);
  }
  const boundaries=[...new Set(crossings)].sort((a,b)=>a-b);
  let best=null;
  function consider(weight,low,high){
   const mse=rankMSE(rows,committeeTeams,weight,headToHead),span=high-low;
   if(!best||mse<best.mse-1e-12||(Math.abs(mse-best.mse)<1e-12&&(span>best.span+1e-12||(Math.abs(span-best.span)<1e-12&&Math.abs(weight-.5)<Math.abs(best.weight-.5))))){best={weight,mse,low,high,span};}
  }
  boundaries.forEach((weight,i)=>{
   consider(weight,weight,weight);
   const next=boundaries[i+1];
   if(next!==undefined&&next-weight>1e-12)consider((weight+next)/2,weight,next);
  });
  return best;
 }

